from collections import defaultdict

def find(parent, i):
    if parent[i] == i:
        return i
    parent[i] = find(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)

    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def maxParticipants(n, k, preferences):
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    for i in range(1, n + 1):
        union(parent, rank, i, preferences[i - 1])

    group_size = defaultdict(int)
    for i in range(1, n + 1):
        group_size[find(parent, i)] += 1

    max_group = 0
    for size in group_size.values():
        if size <= k:
            max_group += size

    return max_group

