import sys
from typing import List

def max_participants(n: int, k: int, preferences: List[int]) -> int:
    parent = list(range(n + 1))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootX] = rootY

    for i in range(1, n + 1):
        union(i, preferences[i - 1])

    groups = {}
    for i in range(1, n + 1):
        root = find(i)
        if root not in groups:
            groups[root] = []
        groups[root].append(i)

    count = 0
    for group in groups.values():
        if len(group) <= k:
            count += len(group)
        else:
            count += k

    return count

